var n=`0313-barbajuan`;var t=`world-0313`;var o=`MC`;var a=`western-europe`;var s=4;var r=62;var l={en:`Barbajuan`,ua:`Барбажуан`};var g={en:`A traditional Monaco dish made with all-purpose flour, swiss chard, spinach, ricotta. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Монако. Основні інгредієнти: пшеничне борошно універсальне, мангольд, шпинат, рикота. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,360,`g`],[`extra-virgin-olive-oil`,65,`ml`],[`water`,155,`ml`],[`table-salt`,3,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:11,i:[[`swiss-chard`,280,`g`],[`spinach`,260,`g`],[`ricotta`,200,`g`],[`chicken-egg`,1,`pcs`],[`parmigiano-reggiano`,60,`g`],[`yellow-onion`,80,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:20,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 11 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 11 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:11,i:[[`sunflower-oil`,650,`ml`]]}];var u={slug:n,id:t,country:`MC`,region:a,servings:4,minutes:62,title:l,text:g,steps:d};export{o as country,u as default,t as id,r as minutes,a as region,s as servings,n as slug,d as steps,g as text,l as title};